WITH flattened AS (SELECT id, plan, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) e AS tier_value), matched_keys AS (SELECT currency, id FROM flattened EXCEPT SELECT currency, id FROM price_tiers WHERE plan = 'pro'), reconciled AS (SELECT s.* FROM flattened s INNER JOIN matched_keys k ON s.currency = k.currency AND s.id = k.id), metrics AS (SELECT id, currency, SUM(tier_value) OVER (PARTITION BY currency, plan) AS currency_sum_tier_value, DENSE_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank, RANK() OVER (ORDER BY tier_value NULLS LAST) AS tier_value_rank, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank_2 FROM reconciled), valid AS (SELECT id, currency, tier_value_dense_rank, tier_value_rank, tier_value_dense_rank_2, ROUND(currency_sum_tier_value, 0) AS currency_sum_tier_value_rounded, CEIL(tier_value_dense_rank_2) AS tier_value_dense_rank_2_whole FROM metrics WHERE tier_value_dense_rank_2 <> 5) SELECT id, currency, tier_value_dense_rank, tier_value_rank, tier_value_dense_rank_2, currency_sum_tier_value_rounded FROM valid ORDER BY tier_value_dense_rank_2 NULLS LAST;
